/** Backend-fixed 6-value category enum, in the exact order the backend groups them for display. */
private val CATEGORY_ORDER = listOf("MOMENTUM", "TREND", "VOLUME", "VOLATILITY", "VALUATION", "EVENT")

/**
 * All 11 `condition_labels`, grouped by category in the backend's own display order, each
 * tap-to-expand to show its `meaning`. Chips render one-per-row rather than as a wrapped cloud --
 * expansion state is per-chip and needs to render its `meaning` directly under that specific chip,
 * which a `FlowRow` of independent peer items can't cleanly do once one item needs to grow taller
 * than its neighbors without disturbing their wrap positions.
 *
 * The "what changed since last run" box is its own thing, not part of `condition_labels` --
 * `chipsAdded`/`chipsRemoved` come from the symbol's cached `StockPreview` (see
 * `StockDetailViewModel`), cross-referenced here since `StockDetail` carries no day-over-day delta
 * of its own but the Design mockups show this box on the Detail screen too.
 */
@Composable
fun SignalConditions(
    conditionLabels: List<DomainConditionLabel>?,
    chipsAdded: List<String>,
    chipsRemoved: List<String>,
    expandedChipIds: Set<String>,
    onToggleChip: (String) -> Unit,
    modifier: Modifier = Modifier
) {
    val labels = conditionLabels.orEmpty()
    if (labels.isEmpty()) return

    Column(modifier = modifier.fillMaxWidth()) {
        SectionDividerLabel(
            title = stringResource(id = R.string.stock_detail_signal_conditions_title, labels.size),
            trailing = stringResource(id = R.string.stock_detail_signal_conditions_hint)
        )
        Spacer()

        if (chipsAdded.isNotEmpty() || chipsRemoved.isNotEmpty()) {
            WhatChangedBox(chipsAdded, chipsRemoved)
            Spacer()
        }

        val grouped = labels.groupBy { it.category?.uppercase() }
        Column(verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_large))) {
            CATEGORY_ORDER.forEach { category ->
                val chipsInCategory = grouped[category].orEmpty()
                if (chipsInCategory.isNotEmpty()) {
                    CategoryGroup(
                        title = categoryLabel(category),
                        chips = chipsInCategory,
                        expandedChipIds = expandedChipIds,
                        onToggleChip = onToggleChip
                    )
                }
            }
        }
    }
}

@Composable
private fun categoryLabel(category: String): String = when (category) {
    "MOMENTUM" -> stringResource(id = R.string.stock_detail_category_momentum)
    "TREND" -> stringResource(id = R.string.stock_detail_category_trend)
    "VOLUME" -> stringResource(id = R.string.stock_detail_category_volume)
    "VOLATILITY" -> stringResource(id = R.string.stock_detail_category_volatility)
    "VALUATION" -> stringResource(id = R.string.stock_detail_category_valuation)
    else -> stringResource(id = R.string.stock_detail_category_event)
}

@Composable
private fun WhatChangedBox(chipsAdded: List<String>, chipsRemoved: List<String>) {
    val pulseColors = LocalPulseColors.current

    PulseCard(style = PulseCardStyle.DATA, modifier = Modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            Text(
                text = stringResource(id = R.string.stock_detail_what_changed_title),
                style = MaterialTheme.typography.labelMedium,
                color = pulseColors.onSurfaceMuted
            )
            androidx.compose.foundation.layout.Spacer(modifier = Modifier.padding(top = dimensionResource(id = R.dimen.padding_medium)))
            FlowRow(horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small))) {
                chipsAdded.forEach { label ->
                    Surface(
                        color = MaterialTheme.colorScheme.background,
                        shape = RoundedCornerShape(dimensionResource(id = R.dimen.corner_radius_pill)),
                        border = BorderStroke(dimensionResource(id = R.dimen.border_thin), pulseColors.signalBullishText)
                    ) {
                        Text(
                            text = stringResource(id = R.string.stock_detail_chip_added, label),
                            style = MaterialTheme.typography.labelMedium,
                            color = pulseColors.signalBullishText,
                            modifier = Modifier.padding(
                                horizontal = dimensionResource(id = R.dimen.padding_medium),
                                vertical = dimensionResource(id = R.dimen.padding_small)
                            )
                        )
                    }
                }
                chipsRemoved.forEach { label ->
                    Text(
                        text = stringResource(id = R.string.stock_detail_chip_removed, label),
                        style = MaterialTheme.typography.labelMedium.copy(textDecoration = TextDecoration.LineThrough),
                        color = pulseColors.onSurfaceMuted,
                        modifier = Modifier.padding(
                            horizontal = dimensionResource(id = R.dimen.padding_medium),
                            vertical = dimensionResource(id = R.dimen.padding_small)
                        )
                    )
                }
            }
        }
    }
}

@Composable
private fun CategoryGroup(
    title: String,
    chips: List<DomainConditionLabel>,
    expandedChipIds: Set<String>,
    onToggleChip: (String) -> Unit
) {
    val pulseColors = LocalPulseColors.current

    Column {
        Text(
            text = title,
            style = MaterialTheme.typography.labelMedium,
            color = pulseColors.onSurfaceMuted
        )
        androidx.compose.foundation.layout.Spacer(modifier = Modifier.padding(top = dimensionResource(id = R.dimen.padding_small)))
        Column(verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_small))) {
            chips.forEach { chip ->
                val label = chip.label ?: return@forEach
                val isExpanded = expandedChipIds.contains(label)
                val (pillColor, textColor) = when (chip.direction?.uppercase()) {
                    "BULLISH" -> pulseColors.signalBullishPill to pulseColors.signalBullishText
                    "BEARISH" -> pulseColors.signalBearishPill to pulseColors.signalBearishText
                    else -> pulseColors.signalNeutralPill to pulseColors.signalNeutralText
                }

                Column(modifier = Modifier.clickable { onToggleChip(label) }) {
                    SignalPill(text = label, pillColor = pillColor, contentColor = textColor)
                    if (isExpanded && chip.meaning != null) {
                        Text(
                            text = chip.meaning,
                            style = MaterialTheme.typography.bodySmall,
                            color = pulseColors.onSurfaceMuted,
                            modifier = Modifier.padding(
                                top = dimensionResource(id = R.dimen.padding_small),
                                start = dimensionResource(id = R.dimen.padding_medium)
                            )
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.padding(top = dimensionResource(id = R.dimen.padding_medium)))
}

